// Generated by spec-lang build: runtime shim rt.store_hygiene_test of the cpp backend (crates/emit-cpp/runtime/tests/rt/store_hygiene_test.cpp), emitted verbatim; do not edit.
// The store's failure paths (docs/contract.md section 3): a refusal writes nothing, an unreadable store is
// left alone, an unwritable directory leaves the old store and no temporary file, a held lock is released,
// and a signal during the write leaves either store whole and no temporary file. Over a toy app, so it
// tests the runtime and not any one program.
#include <dirent.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <expected>
#include <fstream>
#include <optional>
#include <sstream>
#include <string>
#include <string_view>
#include <thread>
#include <variant>
#include <vector>

#include "harness.hpp"
#include "rt/driver.hpp"
#include "rt/file.hpp"
#include "rt/lock.hpp"

namespace {

// A world of one counter: "N\n" on disk.
struct Toy {
  struct Add {};
  struct Refuse {};
  struct Read {};
  using Event = std::variant<Add, Refuse, Read>;
  struct World {
    std::int64_t n = 0;
  };
  static bool writes(const Event& e) { return !std::holds_alternative<Read>(e); }
  static std::optional<World> decode(std::string_view bytes) {
    if (bytes.size() < 2 || bytes.back() != '\n') {
      return std::nullopt;
    }
    std::int64_t n = 0;
    for (const char c : bytes.substr(0, bytes.size() - 1)) {
      if (c < '0' || c > '9') {
        return std::nullopt;
      }
      n = n * 10 + (c - '0');
    }
    return World{n};
  }
  static std::expected<std::string, rt::StoreError> encode(const World& w) {
    return std::to_string(w.n) + "\n";
  }
  static rt::Applied apply(Event e, World& w) {
    if (std::holds_alternative<Refuse>(e)) {
      return {{}, "Refused"};
    }
    if (std::holds_alternative<Add>(e)) {
      ++w.n;
      return {{"added"}, std::nullopt};
    }
    return {{std::to_string(w.n)}, std::nullopt};
  }
};

std::string temp_dir() {
  std::string pattern = "/tmp/rt-store-XXXXXX";
  const char* made = ::mkdtemp(pattern.data());
  harness::check(made != nullptr, "a temporary directory");
  return pattern;
}

std::string slurp(const std::string& path) {
  std::ifstream in(path, std::ios::binary);
  std::stringstream s;
  s << in.rdbuf();
  return s.str();
}

void spit(const std::string& path, std::string_view text) { std::ofstream(path, std::ios::binary) << text; }

// Names in the directory that end in ".tmp".
std::vector<std::string> temporaries(const std::string& dir) {
  std::vector<std::string> out;
  DIR* d = ::opendir(dir.c_str());
  harness::check(d != nullptr, "the directory opens");
  while (const dirent* e = ::readdir(d)) {
    const std::string_view name = e->d_name;
    if (name.ends_with(".tmp")) {
      out.emplace_back(name);
    }
  }
  ::closedir(d);
  return out;
}

ino_t inode(const std::string& path) {
  struct stat s{};
  harness::check(::stat(path.c_str(), &s) == 0, "the store exists");
  return s.st_ino;
}

void remove_all(const std::string& dir) {
  ::chmod(dir.c_str(), 0700);
  const std::string command = "rm -rf '" + dir + "'";
  harness::check(std::system(command.c_str()) == 0, "the temporary directory is removed");
}

}  // namespace

TEST(refusal_writes_nothing) {
  const std::string dir = temp_dir();
  const std::string store = dir + "/store";
  spit(store, "5\n");
  const ino_t before = inode(store);
  const rt::RunResult r = rt::detail::locked<Toy>(Toy::Refuse{}, store);
  CHECK_EQ(r.code, 1);
  CHECK_EQ(slurp(store), "5\n");
  CHECK(inode(store) == before);
  CHECK(temporaries(dir).empty());
  remove_all(dir);
}

TEST(unreadable_store_is_left_alone) {
  const std::string dir = temp_dir();
  const std::string store = dir + "/store";
  spit(store, "not a world");
  const rt::RunResult r = rt::detail::locked<Toy>(Toy::Add{}, store);
  CHECK_EQ(r.code, 3);
  CHECK_EQ(r.err, "error: store " + store + ": unreadable\n");
  CHECK_EQ(slurp(store), "not a world");
  CHECK(temporaries(dir).empty());
  remove_all(dir);
}

TEST(unwritable_directory_keeps_the_old_store) {
  if (::geteuid() == 0) {
    return;  // the superuser writes anywhere: nothing to show
  }
  const std::string dir = temp_dir();
  const std::string store = dir + "/store";
  spit(store, "5\n");
  CHECK_EQ(rt::detail::locked<Toy>(Toy::Read{}, store).out, "5\n");  // creates the lock file
  harness::check(::chmod(dir.c_str(), 0500) == 0, "the directory is made read-only");
  const rt::RunResult r = rt::detail::locked<Toy>(Toy::Add{}, store);
  CHECK_EQ(r.code, 3);
  CHECK_EQ(r.err, "error: store " + store + ": unwritable\n");
  CHECK_EQ(r.out, "");
  CHECK_EQ(slurp(store), "5\n");
  CHECK(temporaries(dir).empty());
  // The lock was released on the failure path: an exclusive lock is had at once.
  CHECK(rt::acquire(store + ".lock", rt::LockMode::Exclusive, {std::chrono::milliseconds(0)}).has_value());
  remove_all(dir);
}

TEST(contention_then_release) {
  const std::string dir = temp_dir();
  const std::string lock = dir + "/store.lock";
  const rt::LockTiming quick{std::chrono::milliseconds(50), std::chrono::milliseconds(10)};
  std::optional<rt::Lock> held;
  {
    auto first = rt::acquire(lock, rt::LockMode::Exclusive, quick);
    CHECK(first.has_value());
    held.emplace(std::move(*first));
  }
  const auto second = rt::acquire(lock, rt::LockMode::Shared, quick);
  CHECK(!second.has_value() && second.error() == rt::StoreError::Contended);
  held.reset();
  CHECK(rt::acquire(lock, rt::LockMode::Exclusive, quick).has_value());
  remove_all(dir);
}

TEST(a_signal_during_the_write_leaves_a_whole_store) {
  const std::string dir = temp_dir();
  const std::string store = dir + "/store";
  const std::string a(1 << 22, 'a');
  const std::string b(1 << 22, 'b');
  for (int round = 0; round < 12; ++round) {
    const pid_t child = ::fork();
    harness::check(child >= 0, "fork");
    if (child == 0) {
      for (int i = 0;; ++i) {
        static_cast<void>(rt::replace_atomically(store, i % 2 == 0 ? a : b));
      }
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(3 + round));
    ::kill(child, SIGTERM);
    int status = 0;
    ::waitpid(child, &status, 0);
    CHECK(WIFSIGNALED(status) && WTERMSIG(status) == SIGTERM);
    CHECK(temporaries(dir).empty());
    const std::string now = slurp(store);
    CHECK(now.empty() || now == a || now == b);
  }
  remove_all(dir);
}
